CREATE TABLE ID_TABLE(ID VARCHAR2(30 BYTE) NOT NULL, NEXT_ID NUMBER(9,0) NOT NULL);
CREATE TABLE CONFIGURAZIONE(IDNODO NUMBER(8,0) NOT NULL, IDENTE VARCHAR2(10 BYTE), IDSPORTELLO VARCHAR2(10 BYTE), ENTE VARCHAR2(50 BYTE), SPORTELLO VARCHAR2(100 BYTE), WSURL VARCHAR2(150 BYTE), USERID VARCHAR2(30 BYTE), PASSWORD VARCHAR2(30 BYTE), IDDIREZIONE VARCHAR2(10 BYTE), DIREZIONE VARCHAR2(50 BYTE) );
CREATE TABLE SICUREZZA (ID NUMBER(8,0) NOT NULL , TOKEN VARCHAR2(32 BYTE) NOT NULL ,SCADENZA DATE, FKIDNODO NUMBER(8,0) NOT NULL );
CREATE TABLE PRATICHE (ID NUMBER(8,0) NOT NULL,IDENTE VARCHAR2(10 BYTE), IDSPORTELLO VARCHAR2(10 BYTE),IDPRATICA VARCHAR2(30 BYTE), NUMPRATICA VARCHAR2(50 BYTE), DATAPRATICA DATE, NUMPROTGEN VARCHAR2(50 BYTE), DATAPROTGEN DATE );
CREATE TABLE MESSAGGIPRATICHE (ID NUMBER(8,0) NOT NULL, FKIDRICHIESTA NUMBER(8,0), FKIDRISPOSTA NUMBER(8,0));
CREATE TABLE ATTIVITA (ID NUMBER(8,0) NOT NULL ,FKIDPRATICHE NUMBER(8,0), IDATTIVITA VARCHAR2(20 BYTE), DATAATTIVITA DATE, NUMPROTGEN VARCHAR2(50 BYTE), DATAPROTGEN DATE, TIPOATTIVITA VARCHAR2(150 BYTE), DATASISTEMA DATE, IDPROCEDIMENTO VARCHAR2(30 BYTE));
CREATE TABLE MESSAGGIATTIVITA (ID NUMBER(8,0) NOT NULL, FKIDRICHIESTA NUMBER(8,0), FKIDRISPOSTA NUMBER(8,0) );

CREATE TABLE VERSIONE 
(
  VERSIONE VARCHAR2(15 CHAR)
) ;